"""Build a lossless, explicit engineering-evidence copyset; no recursive copying."""
from pathlib import Path
from hashlib import sha256
import json
ROOT=next(p for p in Path(__file__).resolve().parents if (p/'src/lupine_discovery/decision_pool.py').is_file())
HERE=Path(__file__).resolve().parent

def main(allowlists):
    destination=HERE/'conformance-promotion-evidence-v2'
    if destination.exists():raise RuntimeError('OUTPUT_ALREADY_EXISTS')
    own=['contract-conformance-proposal-v1.md','contract-conformance-integration-v1.md',
         'run_contract_author.py','build_conformance_bundle.py',
         'reports/contract-author-v1.json','reports/contract-author-v1.log',
         'reports/contract-author-v2.json','reports/contract-author-v2.log',
         'reports/contract-driver-first.log','reports/contract-driver-second.log','reports/contract-driver-third.log',
         'reports/contract-producer-hold-v1.json','reports/contract-producer-hold-v2.json',
         'reports/contract-peer-references-v2.json',
         'pre-decisions-fix-v1/mpea_archive_decisions.py',
         'promotion-contract-v2/manifest-v2.json']
    sources={str((HERE/name).relative_to(ROOT)):None for name in own}
    promotion=json.loads((HERE/'promotion-contract-v2/manifest-v2.json').read_bytes())
    for record in promotion['files']:sources[record['source']]={'bytes':record['bytes'],'sha256':record['sha256']}
    for path in allowlists:
        path=Path(path);value=json.loads((ROOT/path).read_bytes());sources[str(path)]=None
        if type(value.get('files')) is not dict:raise RuntimeError('ALLOWLIST_SCHEMA_REQUIRED')
        for name,identity in value['files'].items():
            if type(name) is not str or type(identity) is not dict:raise RuntimeError('ALLOWLIST_SCHEMA_REQUIRED')
            if name in sources and sources[name] is not None and sources[name]!=identity:raise RuntimeError('COPYSET_CONFLICT')
            sources[name]={'bytes':identity['bytes'],'sha256':identity['sha256']}
    captured=[]
    for name,expected in sorted(sources.items()):
        path=ROOT/name
        if path.is_symlink() or not path.is_file() or '..' in path.parts:raise RuntimeError('UNEXPECTED_SOURCE')
        raw=path.read_bytes();identity={'bytes':len(raw),'sha256':sha256(raw).hexdigest()}
        if expected is not None and identity!=expected:raise RuntimeError('COPYSET_IDENTITY_MISMATCH')
        captured.append((name,raw,identity))
    destination.mkdir();(destination/'artifacts').mkdir();records=[]
    for index,(name,raw,identity) in enumerate(captured,1):
        wrapper={'schema':'lupine.lossless.utf8-evidence.v1','original_path':name,**identity,'utf8':raw.decode('utf-8')}
        encoded=(json.dumps(wrapper,sort_keys=True,indent=2,ensure_ascii=True)+'\n').encode()
        relative=f'artifacts/{index:04d}.json';(destination/relative).write_bytes(encoded)
        restored=json.loads(encoded)['utf8'].encode('utf-8')
        if restored!=raw:raise RuntimeError('RESTORATION_MISMATCH')
        records.append({'original_path':name,**identity,'retained_path':relative,'retained_bytes':len(encoded),'retained_sha256':sha256(encoded).hexdigest(),'encoding':'lossless_utf8_json'})
    manifest={'schema':'lupine.mpea.conformance-evidence-copyset.v2','scope':'explicit constructed-data engineering source/tests/logs/reviews; historical failures preserved; no real archive, feature table, target or allocation artifacts',
        'artifacts':records,'artifact_count':len(records),'original_bytes':sum(r['bytes'] for r in records),
        'retained_artifact_bytes':sum(r['retained_bytes'] for r in records),'all_restored_bytes_verified':True,
        'separate_peer_evidence':json.loads((HERE/'reports/contract-peer-references-v2.json').read_bytes())}
    raw=(json.dumps(manifest,sort_keys=True,indent=2)+'\n').encode();(destination/'copy-manifest-v2.json').write_bytes(raw)
    readme=('# MPEA prospective conformance engineering evidence\n\n'
        'Every original named artifact is stored losslessly in a UTF-8 JSON wrapper. '
        'Decode its `utf8` string and encode as UTF-8 to recover exact bytes; check '
        'the original byte count/SHA-256. No trailing whitespace was normalized.\n\n'
        'This evidence covers constructed-data engineering only. Earlier failed '
        'tests and producer versions remain labeled as historical. It is not a '
        'scientific registration, actual target-read receipt or performance result. '
        'No recursively copied attempt directory, real archive or feature table is included.\n')
    (destination/'README.md').write_text(readme)
    seal={'schema':'lupine.evidence-bundle-seal.v1','files':{str(p.relative_to(destination)):{'bytes':p.stat().st_size,'sha256':sha256(p.read_bytes()).hexdigest()} for p in sorted(destination.rglob('*')) if p.is_file()}}
    (destination/'bundle-seal-v2.json').write_text(json.dumps(seal,sort_keys=True,indent=2)+'\n')
    print(json.dumps({'artifacts':manifest['artifact_count'],'original_bytes':manifest['original_bytes'],'retained_bytes':sum(v['bytes'] for v in seal['files'].values()),'manifest_sha256':sha256(raw).hexdigest(),'bundle_seal_sha256':sha256((destination/'bundle-seal-v2.json').read_bytes()).hexdigest()},sort_keys=True))
if __name__=='__main__':
    import sys
    main(sys.argv[1:])
